{
  "kc_id": "KC_CLU_DBS_001",
  "canonical_name": "Core Point",
  "definition": {
    "status": "abstained",
    "grounding_mode": "abstained",
    "text": "",
    "supporting_evidence_ids": [],
    "supporting_lanes": [],
    "abstention_reason": "The provided evidence mentions core points in the context of their relationship to border points and clusters, but does not provide a definition of what a core point is."
  },
  "scope": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "In the DBSCAN algorithm, core points that are within a distance Eps of each other are placed in the same cluster; additionally, any border point located within the neighborhood of a core point is also assigned to that core point's cluster.",
    "supporting_evidence_ids": [
      "E5",
      "E7"
    ],
    "supporting_lanes": [
