{
  "kc_id": "KC_CLU_EVAL_002",
  "canonical_name": "SSE (Cluster Quality)",
  "definition": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "Sum of the squared error (SSE), also known as scatter, is an objective function used to measure clustering quality. It is calculated by computing the total sum of the squared Euclidean distances from each data point to its closest centroid.",
    "supporting_evidence_ids": [
      "E2"
    ],
    "supporting_lanes": [
      "context_lane"
    ],
    "abstention_reason": ""
  },
  "scope": {
    "status": "grounded",
    "grounding_mode": "contextual_synthesis",
    "text": "SSE is used to compare different K-means clustering results, where a lower SSE indicates that the centroids are a better representation of the points in their cluster and generally reflects better clustering results.",
    "supporting_evidence_ids": [
      "E2",
      "E3"
    ],
    "supporting_lanes": [
      "context_lane",
      "scope_lane"
    ],
    "abstention_reason": ""
  }
}

